:where([data-moru-registry]) .ui-label {
  font-family: var(--ui-font-family, inherit);
  color: var(--ui-text, #171717);
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.01em);
  box-sizing: border-box;
}
:where([data-moru-registry]) .ui-label {
  display: inline-block;
  cursor: default;
  overflow-wrap: anywhere;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { forwardRef, type LabelHTMLAttributes } from 'react'
import { cn } from './_lib/cn'
import { useFieldContext } from './field-context'
import './controls-shared.css'
import './label.css'

export type LabelProps = LabelHTMLAttributes<HTMLLabelElement>
export const Label = forwardRef<HTMLLabelElement, LabelProps>(function Label(
  { htmlFor, className, ...props },
  ref,
) {
  const field = useFieldContext()
  return (
    <label
      {...props}
      ref={ref}
      htmlFor={htmlFor ?? field?.controlId}
      className={cn('ui-label', className)}
    />
  )
})
